import { css } from 'lit';

export const accordionItemStyles = css`
  :host {
    display: block;
    border-bottom: 1px solid var(--bl-color-neutral-200);
  }

  :host(:first-of-type) {
    border-top: 1px solid var(--bl-color-neutral-200);
  }

  :host([disabled]) {
    opacity: 0.5;
    pointer-events: none;
  }

  .trigger {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: var(--bl-spacing-md) 0;
    background: none;
    border: none;
    cursor: pointer;
    font-family: var(--bl-font-family-base);
    font-size: var(--bl-font-size-md);
    font-weight: 500;
    color: var(--bl-color-neutral-900);
    text-align: left;
    line-height: 1.5;
  }

  .trigger:hover {
    color: var(--bl-color-neutral-700);
  }

  .trigger:focus-visible {
    outline: 2px solid var(--bl-focus-ring-color);
    outline-offset: 2px;
    border-radius: var(--bl-radius-sm);
  }

  .chevron {
    width: 20px;
    height: 20px;
    flex-shrink: 0;
    color: var(--bl-color-neutral-500);
    transition: transform var(--bl-transition-fast);
  }

  :host([open]) .chevron {
    transform: rotate(180deg);
  }

  .panel {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows var(--bl-transition-normal);
  }

  :host([open]) .panel {
    grid-template-rows: 1fr;
  }

  .panel-inner {
    overflow: hidden;
  }

  .panel-content {
    padding-bottom: var(--bl-spacing-md);
    color: var(--bl-color-neutral-600);
    font-size: var(--bl-font-size-sm);
    line-height: 1.6;
  }
`;

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { accordionItemStyles } from './accordion-item.styles.js';

/**
 * An individual accordion item with a trigger and collapsible panel.
 *
 * @element bl-accordion-item
 * @slot trigger - The header/trigger content.
 * @slot - Default slot for the panel content.
 * @fires bl-accordion-toggle - Emitted when item is toggled.
 */
@customElement('bl-accordion-item')
export class BlAccordionItem extends LitElement {
  static override styles = [tokens, accordionItemStyles];

  private _headerId = `bl-acc-h-${Math.random().toString(36).slice(2, 9)}`;
  private _panelId = `bl-acc-p-${Math.random().toString(36).slice(2, 9)}`;

  /** Whether this item is expanded. */
  @property({ type: Boolean, reflect: true })
  open = false;

  /** Whether this item is disabled. */
  @property({ type: Boolean, reflect: true })
  disabled = false;

  /** A unique value identifying this item within the accordion. */
  @property()
  value = '';

  private _handleClick(): void {
    if (this.disabled) return;
    this.dispatchEvent(
      new CustomEvent('bl-accordion-toggle', {
        detail: { value: this.value, open: !this.open },
        composed: true,
        bubbles: true,
      }),
    );
  }

  private _handleKeyDown(e: KeyboardEvent): void {
    if (this.disabled) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      this._handleClick();
    }
  }

  protected override render() {
    return html`
      <button
        class="trigger"
        id=${this._headerId}
        part="trigger"
        aria-expanded=${this.open ? 'true' : 'false'}
        aria-controls=${this._panelId}
        aria-disabled=${this.disabled ? 'true' : 'false'}
        @click=${this._handleClick}
        @keydown=${this._handleKeyDown}
      >
        <slot name="trigger"></slot>
        <svg
          class="chevron"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
          aria-hidden="true"
        >
          <polyline points="6 9 12 15 18 9"></polyline>
        </svg>
      </button>
      <div
        class="panel"
        id=${this._panelId}
        role="region"
        aria-labelledby=${this._headerId}
      >
        <div class="panel-inner">
          <div class="panel-content" part="content">
            <slot></slot>
          </div>
        </div>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-accordion-item': BlAccordionItem;
  }
}

import { css } from 'lit';

export const accordionStyles = css`
  :host {
    display: block;
  }
`;

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { accordionStyles } from './accordion.styles.js';
import type { BlAccordionItem } from './accordion-item.js';

/**
 * A container for accordion items. Manages which items are open.
 *
 * @element bl-accordion
 * @slot - `bl-accordion-item` elements.
 * @fires bl-change - Emitted when the open items change.
 */
@customElement('bl-accordion')
export class BlAccordion extends LitElement {
  static override styles = [tokens, accordionStyles];

  /** Allow multiple items to be open simultaneously. */
  @property({ type: Boolean })
  multiple = false;

  override connectedCallback(): void {
    super.connectedCallback();
    this.addEventListener('bl-accordion-toggle', this._handleToggle as EventListener);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('bl-accordion-toggle', this._handleToggle as EventListener);
  }

  private _handleToggle = (e: CustomEvent<{ value: string; open: boolean }>): void => {
    e.stopPropagation();
    const { value, open } = e.detail;

    const items = this._getItems();

    if (open) {
      if (!this.multiple) {
        // Close all others
        items.forEach((item) => {
          if (item.value !== value) item.open = false;
        });
      }
      const target = items.find((item) => item.value === value);
      if (target) target.open = true;
    } else {
      const target = items.find((item) => item.value === value);
      if (target) target.open = false;
    }

    const openValues = items.filter((item) => item.open).map((item) => item.value);
    this.dispatchEvent(
      new CustomEvent('bl-change', {
        detail: { value: this.multiple ? openValues : openValues[0] ?? '' },
        composed: true,
        bubbles: true,
      }),
    );
  };

  private _getItems(): BlAccordionItem[] {
    return Array.from(this.querySelectorAll<BlAccordionItem>('bl-accordion-item'));
  }

  private _handleKeyDown = (e: KeyboardEvent): void => {
    const triggers = this._getItems()
      .filter((item) => !item.disabled)
      .map(
        (item) =>
          item.shadowRoot?.querySelector<HTMLElement>('.trigger'),
      )
      .filter(Boolean) as HTMLElement[];

    const current = triggers.indexOf(
      (e.target as HTMLElement)?.closest('bl-accordion-item')
        ?.shadowRoot?.querySelector<HTMLElement>('.trigger') ?? (null as never),
    );
    if (current === -1) return;

    let next = -1;
    if (e.key === 'ArrowDown') {
      next = current + 1 >= triggers.length ? 0 : current + 1;
    } else if (e.key === 'ArrowUp') {
      next = current - 1 < 0 ? triggers.length - 1 : current - 1;
    } else if (e.key === 'Home') {
      next = 0;
    } else if (e.key === 'End') {
      next = triggers.length - 1;
    }

    if (next !== -1) {
      e.preventDefault();
      triggers[next]?.focus();
    }
  };

  protected override render() {
    return html`<slot @keydown=${this._handleKeyDown}></slot>`;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-accordion': BlAccordion;
  }
}
